# 69_gender_benchmark_misconduct.R
#
# Are women under/over-represented among the "bad behaviour" cases in Ch3
# (Figure 3.3 Commons misconduct series, and the separate Lords list)? PJ,
# 12 Sep 2026: raised whether the low raw count of women among these cases
# is "worth mentioning esp if v low" — then pushed the method twice: (1)
# "gender MP needs to reflect gender imbalance on commons at time it
# happened", i.e. each case must be benchmarked against the ACTUAL women's
# share of the chamber in the specific year/Parliament it occurred, not one
# flat overall rate; (2) "is the 2 versus 3.2 statistically significant
# using small stats" — an exact small-sample test, not a normal
# approximation.
#
# METHOD: each case is an independent Bernoulli trial with its OWN
# probability (the chamber's actual women's share that year) — NOT a
# single shared p, so a standard binomial test is the wrong tool. The
# correct distribution for a sum of independent, non-identical Bernoulli
# trials is the Poisson-binomial, computed here by exact dynamic
# programming (not simulated, not approximated).
#
# BENCHMARKS:
#   Commons — exact, sourced per-election women's-MP-share figures
#     (Commons Library / Institute for Government, verified via WebSearch
#     12 Sep 2026): 2005=19.8%, 2010=23%, 2015=29%, 2017=32%, 2019=34%,
#     2024=40%.
#   Lords — read directly off two real charts (embedded as images, not
#     extractable text — rendered and read per
#     [[reference-scrambled-pdf-method]]):
#     (a) Wakeham Commission report on Lords reform (Cm 4534, 2000),
#         Chapter 2, "Percentage of women in the House of Lords 1958-2000"
#         — hosted on assets.publishing.service.gov.uk, not parliament.uk,
#         so not Cloudflare-blocked. Gives 1980 ≈5%.
#     (b) House of Lords Library, "Women in the House of Lords: 65 years
#         on" (17 May 2023) — PJ opened this manually (parliament.uk is
#         Cloudflare-blocked to automated fetch) and saved it to
#         `data/`. Figure 1 gives the full 1958-2022 annual series; read
#         directly: 2001≈16%, 2005≈19%, 2009-10≈20%, 2011≈21%, 2015≈25%,
#         2018≈27%, 2020≈28%. Both charts agree on the 1980 anchor
#         independently (≈5% each), which is reassuring.
#     Both source PDFs archived at
#     sources_raw/lords_gender_composition/SOURCE_NOTE.md.
#
# ⚠ CAVEAT, stated once, applies to the whole Lords side of this script:
#   the Lords case list is NOT a systematic census (unlike the Commons
#   Mortimore & Blick series) — it is PJ's own web-search-compiled
#   illustrative list. This test's numerator therefore carries real
#   undercount/survivorship-bias risk that the Commons test does not.
#
# OUTPUT: prints results to console; FIG_GENDER_BENCHMARK_NOTES.md

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT

poisson_binomial_pmf <- function(probs) {
  dp <- 1
  for (p in probs) {
    dp <- c(dp * (1 - p), 0) + c(0, dp * p)
  }
  dp
}

report <- function(label, probs, observed) {
  pmf <- poisson_binomial_pmf(probs)
  ex  <- sum(probs)
  p_le <- sum(pmf[1:(observed + 1)])
  cat(sprintf("\n=== %s ===\n", label))
  cat(sprintf("n = %d, E[X] = %.2f, observed = %d\n", length(probs), ex, observed))
  cat(sprintf("Exact Poisson-binomial P(X<=%d) = %.4f\n", observed, p_le))
  list(label = label, n = length(probs), expected = ex, observed = observed, p_value = p_le)
}

